import "core-js/modules/es6.function.name";
import { ModelApi } from "@/api/workflow/modeling/modelApi";
import hussarRequest from '@/views/workflow/util/request';
import flowfile from "../components/flowFile/flowfile";
import VersionManage from "../components/VersionMange";
export default {
  name: 'modeling',
  components: {
    flowfile: flowfile,
    VersionManage: VersionManage
  },
  // 流程管理页面
  data: function data() {
    return {
      url: window.baseUrl,
      showPicFlag: false,
      showVersions: false,
      showPicProcessInstanceId: '',
      showPicProcessKey: null,
      // 查询条件
      listQuery: {
        modelName: '',
        page: 1,
        size: 10
      },
      uploadUrl: '/model/modelImport',
      address: '',
      // 列表数据
      list: [],
      listLoading: false,
      // 列表选择的数据集合
      checkBoxData: [],
      // 总页数
      total: 0,
      mykey: '',
      pageCount: 7,
      // 分页参数
      page: {
        currentPage: 1,
        size: 10,
        sizes: [10, 20, 50, 100]
      }
    };
  },
  mounted: function mounted() {
    this.queryModel();
  },
  methods: {
    // 工作流查看
    showBpm: function showBpm(data) {
      this.showPicFlag = true;
      this.showPicProcessInstanceId = data.processKey;
      this.showPicProcessKey = data.processKey;
    },
    close: function close() {
      this.showPicFlag = false;
    },
    // 设置序号
    indexMethod: function indexMethod(index) {
      var curpage = this.page.currentPage;
      var limitpage = this.listQuery.size;
      return index + 1 + (curpage - 1) * limitpage;
    },
    // 查询列表的数据
    queryModel: function queryModel(isReset) {
      var _this = this;
      if (isReset) {
        this.listQuery.page = 1;
        this.page.currentPage = 1;
      }
      this.listLoading = true;
      this.listQuery.current = this.listQuery.page;
      hussarRequest.get(ModelApi.list, this.listQuery).then(function (res) {
        if (res.code === 10000) {
          _this.listLoading = false;
          _this.list = res.data.records;
          _this.total = res.data.total;
        } else {
          _this.listLoading = false;
        }
      }).catch(function (res) {
        _this.listLoading = false;
      });
    },
    // 删除
    deleteModel: function deleteModel(row) {
      var _this2 = this;
      var modelId = row.modelId;
      var name = row.name;
      var msg = '此操作将删除<span class="msg-highlight">"' + name + '"</span>，删除的数据无法恢复';
      this.$confirm(msg, this.$hussarT('hussar-common.confirmedToDeleteNew'), {
        confirmButtonText: this.$hussarT('hussar-common.delete'),
        cancelButtonText: this.$hussarT('hussar-common.cancel'),
        cancelButtonClass: 'dialog-cancel',
        confirmButtonClass: 'dialog-delete',
        closeOnClickModal: false,
        dangerouslyUseHTMLString: true,
        showClose: false,
        customClass: 'lcdp-message',
        type: 'warning'
      }).then(function (res) {
        hussarRequest.post(ModelApi.delete, modelId + '').then(function (res) {
          if (res.code === 10000) {
            _this2.$message.success(_this2.$hussarT('hussar-modeling.deleteSuccess'));
            _this2.queryModel();
          }
        }).catch(function (res) {});
      });
    },
    // 发布
    deployModel: function deployModel(modelId) {
      var _this3 = this;
      var data = {
        modelId: modelId
      };
      // document.body.classList.add("modal-parent");
      this.$confirm(this.$hussarT('hussar-modelEdit.sureRelease'), this.$hussarT('hussar-common.notice'), {
        confirmButtonText: this.$hussarT('hussar-common.confirm'),
        cancelButtonText: this.$hussarT('hussar-common.cancel'),
        cancelButtonClass: 'dialog-cancel',
        confirmButtonClass: 'dialog-save',
        closeOnClickModal: false,
        customClass: 'lcdp-message',
        showClose: false,
        type: 'warning'
      }).then(function (res) {
        hussarRequest.get(ModelApi.deployModel, data).then(function (res) {
          if (res.code === 10000) {
            _this3.$message.success(_this3.$hussarT('hussar-modelEdit.relSuccess'));
            _this3.queryModel();
          }
        }).catch(function (res) {});
      });
    },
    // 版本管理
    versionManagement: function versionManagement(mykey) {
      this.mykey = mykey;
      this.showVersions = true;
    },
    // 重置按钮
    clearData: function clearData() {
      this.listQuery.modelName = '';
      this.queryModel(true);
    },
    // 描述
    descriptionFormat: function descriptionFormat(row) {
      // eslint-disable-next-line no-undef
      return JSON.parse(row.description).description;
    },
    // 选择列表数据
    changeFun: function changeFun(val) {
      this.checkBoxData = val;
    },
    selectAll: function selectAll() {
      if (this.list.length == 0) {
        this.$refs.tableRow.clearSelection();
      }
    },
    // 每页条数改变
    handleSizeChange: function handleSizeChange(val) {
      // 改变每页显示的条数
      this.listQuery.size = val;
      // 注意：在改变每页显示的条数时，要将页码显示到第一页
      this.listQuery.page = 1;
      this.queryModel();
    },
    // 页码切换
    handleCurrentChange: function handleCurrentChange(val) {
      this.listQuery.page = val;
      this.queryModel();
    }
  }
};
